def transform(g):
    from collections import Counter
    colors=Counter(v for row in g for v in row if v != 6)
    bg=colors.most_common(1)[0][0]
    target=next(c for c in colors if c != bg)
    sep_rows=[i for i,row in enumerate(g) if all(v==6 for v in row)]
    rg=[]; s=0
    for r in sep_rows+[len(g)]:
        if r>s: rg.append((s,r))
        s=r+1
    sep_cols=[c for c in range(len(g[0])) if all(row[c]==6 for row in g)]
    cg=[]; s=0
    for c in sep_cols+[len(g[0])]:
        if c>s: cg.append((s,c))
        s=c+1
    return [[1 if sum(g[r][c]==target for r in range(a,b) for c in range(x,y))>=2 else bg for x,y in cg] for a,b in rg]
